gtu(){return"\u0411\u0435\u0437 \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0443 \u0432\u043f\u0440\u0430\u0432 \u0456 \u0433\u043e\u0442\u043e\u0432\u0438\u0445 \u043f\u0440\u043e\u0433\u0440\u0430\u043c. \u0412\u0438 \u043d\u0430\u0437\u0438\u0432\u0430\u0454\u0442\u0435 \u0440\u0443\u0445\u0438 \u0441\u0432\u043e\u0457\u043c\u0438 \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u2014 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u0432\u0435\u0434\u0435 \u0437\u0430 \u043d\u0438\u043c\u0438 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0443."},
gux(){return"\u041f\u043e\u0448\u0443\u043a \u0432 \u0456\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0456\u0457"},
guw(){return"\u041d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0437\u043d\u0430\u0439\u0434\u0435\u043d\u043e."},
