gwf(){return"\u0420\u0456\u0432\u043d\u0438\u0439 \u0440\u0438\u0442\u043c, \u043d\u0430 \u044f\u043a\u043e\u043c\u0443 \u043c\u043e\u0436\u043d\u0430 \u043f\u0440\u0430\u0446\u044e\u0432\u0430\u0442\u0438 \u0440\u043e\u043a\u0430\u043c\u0438. \u042f\u043a\u0449\u043e \u0442\u0440\u0435\u043d\u0443\u0432\u0430\u043d\u043d\u044f \u0432\u0430\u0436\u043a\u0456, \u0440\u0430\u0437 \u043d\u0430 \u043a\u0456\u043b\u044c\u043a\u0430 \u043c\u0456\u0441\u044f\u0446\u0456\u0432 \u0431\u0435\u0440\u0456\u0442\u044c \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u043d\u043a\u0443 \u2014 \u043a\u0440\u0430\u0449\u0435 \u0437\u0430\u0437\u0434\u0430\u043b\u0435\u0433\u0456\u0434\u044c, \u043d\u0456\u0436 \u043a\u043e\u043b\u0438 \u0432\u0430\u0433\u0438 \u0441\u0442\u0430\u043d\u0443\u0442\u044c."},
